package br.gov.dere.persistence;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="dere_validation_audit") public class DereValidationAuditEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="user_id") private Long userId; @Column(name="entity_id") private Long entityId; private String operation,eventType; private boolean valid; @Lob private String errors,payloadXml,payloadCsv; @Column(name="batch_size_bytes") private Long batchSizeBytes; @Column(name="created_at") private Instant createdAt=Instant.now(); protected DereValidationAuditEntity(){} public DereValidationAuditEntity(Long u,Long e,String o,String t,boolean v,String err,String xml,String csv){userId=u;entityId=e;operation=o;eventType=t;valid=v;errors=err;payloadXml=xml;payloadCsv=csv;batchSizeBytes=xml==null?0L:(long)xml.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;} public Long getId(){return id;} public boolean isValid(){return valid;} public Instant getCreatedAt(){return createdAt;} public String getPayloadXml(){return payloadXml;} public String getPayloadCsv(){return payloadCsv;} public String getErrors(){return errors;}}
